using System;
using System.Collections.Generic;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class PaginatedListTests
    {
        #region Constructor Tests

        [Fact]
        public void Constructor_ValidInputs_SetsPropertiesCorrectly()
        {
            // Arrange
            var items = new List<string> { "a", "b", "c" };
            int totalCount = 10;
            int pageIndex = 2;
            int pageSize = 3;

            // Act
            var list = new PaginatedList<string>(items, totalCount, pageIndex, pageSize);

            // Assert
            Assert.Equal(2, list.PageIndex);
            Assert.Equal(4, list.TotalPages); // ceil(10/3) = 4
            Assert.Equal(3, list.Count);
            Assert.Equal("a", list[0]);
            Assert.Equal("b", list[1]);
            Assert.Equal("c", list[2]);
        }

        [Theory]
        [InlineData(10, 3, 4)]   // ceil(10/3) = 4
        [InlineData(9, 3, 3)]    // exact division
        [InlineData(1, 5, 1)]    // single item, large page
        [InlineData(0, 5, 0)]    // no items
        [InlineData(11, 5, 3)]   // ceil(11/5) = 3
        public void Constructor_VariousCounts_CalculatesTotalPagesCorrectly(int count, int pageSize, int expectedTotalPages)
        {
            // Arrange & Act
            var list = new PaginatedList<int>(new List<int>(), count, 1, pageSize);

            // Assert
            Assert.Equal(expectedTotalPages, list.TotalPages);
        }

        #endregion

        #region HasPreviousPage Tests

        [Theory]
        [InlineData(1, false)]   // first page — no previous
        [InlineData(2, true)]    // second page — has previous
        [InlineData(5, true)]    // deep page — has previous
        public void HasPreviousPage_VariousPageIndices_ReturnsExpected(int pageIndex, bool expected)
        {
            var list = new PaginatedList<int>(new List<int>(), 50, pageIndex, 10);
            Assert.Equal(expected, list.HasPreviousPage);
        }

        #endregion

        #region HasNextPage Tests

        [Theory]
        [InlineData(1, 10, 5, true)]   // page 1 of 2 — has next
        [InlineData(2, 10, 5, false)]  // page 2 of 2 — no next
        [InlineData(1, 5, 5, false)]   // single page — no next
        [InlineData(3, 20, 5, true)]   // page 3 of 4 — has next
        [InlineData(4, 20, 5, false)]  // page 4 of 4 — no next (last page)
        public void HasNextPage_VariousCombinations_ReturnsExpected(int pageIndex, int totalCount, int pageSize, bool expected)
        {
            var list = new PaginatedList<int>(new List<int>(), totalCount, pageIndex, pageSize);
            Assert.Equal(expected, list.HasNextPage);
        }

        #endregion

        #region Create Tests

        [Fact]
        public void Create_FirstPage_ReturnsCorrectSlice()
        {
            // Arrange
            var source = Enumerable.Range(1, 25).AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(source, 1, 10);

            // Assert
            Assert.Equal(10, result.Count);
            Assert.Equal(1, result.PageIndex);
            Assert.Equal(3, result.TotalPages); // ceil(25/10) = 3
            Assert.Equal(1, result[0]);
            Assert.Equal(10, result[9]);
            Assert.True(result.HasNextPage);
            Assert.False(result.HasPreviousPage);
        }

        [Fact]
        public void Create_MiddlePage_ReturnsCorrectSlice()
        {
            // Arrange
            var source = Enumerable.Range(1, 25).AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(source, 2, 10);

            // Assert
            Assert.Equal(10, result.Count);
            Assert.Equal(2, result.PageIndex);
            Assert.Equal(11, result[0]);
            Assert.Equal(20, result[9]);
            Assert.True(result.HasNextPage);
            Assert.True(result.HasPreviousPage);
        }

        [Fact]
        public void Create_LastPage_ReturnsPartialSlice()
        {
            // Arrange
            var source = Enumerable.Range(1, 25).AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(source, 3, 10);

            // Assert
            Assert.Equal(5, result.Count);
            Assert.Equal(3, result.PageIndex);
            Assert.Equal(21, result[0]);
            Assert.Equal(25, result[4]);
            Assert.False(result.HasNextPage);
            Assert.True(result.HasPreviousPage);
        }

        [Fact]
        public void Create_EmptySource_ReturnsEmptyList()
        {
            // Arrange
            var source = Enumerable.Empty<int>().AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(source, 1, 10);

            // Assert
            Assert.Empty(result);
            Assert.Equal(1, result.PageIndex);
            Assert.Equal(0, result.TotalPages);
            Assert.False(result.HasNextPage);
            Assert.False(result.HasPreviousPage);
        }

        [Fact]
        public void Create_SingleItem_ReturnsSingleItemPage()
        {
            // Arrange
            var source = new[] { 42 }.AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(source, 1, 10);

            // Assert
            Assert.Single(result);
            Assert.Equal(42, result[0]);
            Assert.Equal(1, result.TotalPages);
            Assert.False(result.HasNextPage);
            Assert.False(result.HasPreviousPage);
        }

        [Fact]
        public void Create_ExactPageSize_NoPartialPage()
        {
            // Arrange — 20 items, page size 10 => exactly 2 full pages
            var source = Enumerable.Range(1, 20).AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(source, 2, 10);

            // Assert
            Assert.Equal(10, result.Count);
            Assert.Equal(2, result.TotalPages);
            Assert.False(result.HasNextPage);
            Assert.True(result.HasPreviousPage);
            Assert.Equal(11, result[0]);
        }

        #endregion
    }
}

using System;
using System.Collections.Concurrent;
using System.Linq;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Xunit;

namespace ContosoUniversity.Tests.Services
{
    public class NotificationServiceTests : IDisposable
    {
        private readonly NotificationService _sut;

        public NotificationServiceTests()
        {
            // Drain the static queue before each test to isolate state
            var drainer = new NotificationService();
            while (drainer.ReceiveNotification() != null) { }
            drainer.Dispose();

            _sut = new NotificationService();
        }

        public void Dispose()
        {
            _sut.Dispose();
        }

        #region SendNotification Tests

        [Fact]
        public void SendNotification_WithDisplayName_CreatesCorrectMessage()
        {
            // Arrange & Act
            _sut.SendNotification("Student", "42", "John Doe", EntityOperation.CREATE, "admin");

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("42", notification.EntityId);
            Assert.Equal("CREATE", notification.Operation);
            Assert.Equal("New Student 'John Doe' has been created", notification.Message);
            Assert.Equal("admin", notification.CreatedBy);
            Assert.False(notification.IsRead);
        }

        [Fact]
        public void SendNotification_WithoutDisplayName_UsesIdInMessage()
        {
            // Arrange & Act
            _sut.SendNotification("Course", "1050", null, EntityOperation.UPDATE, "teacher");

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Course (ID: 1050) has been updated", notification.Message);
            Assert.Equal("teacher", notification.CreatedBy);
        }

        [Fact]
        public void SendNotification_WithoutUserName_DefaultsToSystem()
        {
            // Act
            _sut.SendNotification("Department", "5", "Math", EntityOperation.DELETE);

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("System", notification.CreatedBy);
        }

        [Fact]
        public void SendNotification_OverloadWithoutDisplayName_CreatesNotification()
        {
            // Act
            _sut.SendNotification("Instructor", "7", EntityOperation.CREATE);

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Instructor", notification.EntityType);
            Assert.Equal("7", notification.EntityId);
            Assert.Contains("Instructor (ID: 7)", notification.Message);
        }

        [Theory]
        [InlineData(EntityOperation.CREATE, "New Student 'Alice' has been created")]
        [InlineData(EntityOperation.UPDATE, "Student 'Alice' has been updated")]
        [InlineData(EntityOperation.DELETE, "Student 'Alice' has been deleted")]
        public void SendNotification_AllOperations_GeneratesCorrectMessage(EntityOperation operation, string expectedMessage)
        {
            // Act
            _sut.SendNotification("Student", "1", "Alice", operation, "admin");

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal(expectedMessage, notification.Message);
            Assert.Equal(operation.ToString(), notification.Operation);
        }

        [Fact]
        public void SendNotification_SetsCreatedAtToRecentTime()
        {
            // Arrange
            var before = DateTime.Now.AddSeconds(-2);

            // Act
            _sut.SendNotification("Student", "1", "Test", EntityOperation.CREATE, "user");

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.True(notification.CreatedAt >= before, "CreatedAt should be recent");
            Assert.True(notification.CreatedAt <= DateTime.Now.AddSeconds(2), "CreatedAt should not be in the future");
        }

        #endregion

        #region ReceiveNotification Tests

        [Fact]
        public void ReceiveNotification_EmptyQueue_ReturnsNull()
        {
            // Act
            var result = _sut.ReceiveNotification();

            // Assert
            Assert.Null(result);
        }

        [Fact]
        public void ReceiveNotification_MultipleMessages_ReturnsFIFOOrder()
        {
            // Arrange
            _sut.SendNotification("A", "1", "First", EntityOperation.CREATE);
            _sut.SendNotification("B", "2", "Second", EntityOperation.UPDATE);
            _sut.SendNotification("C", "3", "Third", EntityOperation.DELETE);

            // Act & Assert — FIFO order
            var first = _sut.ReceiveNotification();
            Assert.Equal("A", first!.EntityType);
            Assert.Equal("1", first.EntityId);

            var second = _sut.ReceiveNotification();
            Assert.Equal("B", second!.EntityType);

            var third = _sut.ReceiveNotification();
            Assert.Equal("C", third!.EntityType);

            // Queue should be empty now
            Assert.Null(_sut.ReceiveNotification());
        }

        [Fact]
        public void ReceiveNotification_AfterDequeue_QueueShrinks()
        {
            // Arrange
            _sut.SendNotification("X", "1", EntityOperation.CREATE);
            _sut.SendNotification("Y", "2", EntityOperation.CREATE);

            // Act
            var first = _sut.ReceiveNotification();

            // Assert — first dequeued, second remains
            Assert.Equal("X", first!.EntityType);
            var second = _sut.ReceiveNotification();
            Assert.Equal("Y", second!.EntityType);
            Assert.Null(_sut.ReceiveNotification());
        }

        #endregion

        #region MarkAsRead Tests

        [Fact]
        public void MarkAsRead_DoesNotThrow()
        {
            // MarkAsRead is a no-op but should not throw
            var ex = Record.Exception(() => _sut.MarkAsRead(999));
            Assert.Null(ex);
        }

        #endregion

        #region Dispose Tests

        [Fact]
        public void Dispose_DoesNotThrow()
        {
            var service = new NotificationService();
            var ex = Record.Exception(() => service.Dispose());
            Assert.Null(ex);
        }

        #endregion

        #region WhiteSpace DisplayName Tests

        [Fact]
        public void SendNotification_EmptyStringDisplayName_UsesIdInMessage()
        {
            // Act — empty string should be treated like null (whitespace check)
            _sut.SendNotification("Student", "99", "", EntityOperation.CREATE);

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Contains("ID: 99", notification.Message);
        }

        [Fact]
        public void SendNotification_WhitespaceOnlyDisplayName_UsesIdInMessage()
        {
            // Act
            _sut.SendNotification("Student", "99", "   ", EntityOperation.UPDATE);

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Contains("ID: 99", notification.Message);
        }

        #endregion
    }
}

