            Assert.NotNull(result);
            Assert.Same(course, result.Model);
        }

        [Fact]
        public void Create_POST_InvalidImageExtension_AddsModelError()
        {
            // Arrange
            var course = new Course { CourseID = 7777, Title = "Test", Credits = 3, DepartmentID = 1 };
            var fileMock = new Mock<IFormFile>();
            fileMock.Setup(f => f.Length).Returns(100);
            fileMock.Setup(f => f.FileName).Returns("test.exe");

            // Act
            var result = _controller.Create(course, fileMock.Object) as ViewResult;

            // Assert
            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
            var errorMsg = _controller.ModelState["teachingMaterialImage"]!.Errors[0].ErrorMessage;
            Assert.Contains("valid image file", errorMsg);
        }

        [Fact]
        public void Create_POST_FileTooLarge_AddsModelError()
        {
            // Arrange
            var course = new Course { CourseID = 6666, Title = "Test", Credits = 3, DepartmentID = 1 };
            var fileMock = new Mock<IFormFile>();
            fileMock.Setup(f => f.Length).Returns(6 * 1024 * 1024); // 6MB > 5MB limit
            fileMock.Setup(f => f.FileName).Returns("big.jpg");

            // Act
            var result = _controller.Create(course, fileMock.Object) as ViewResult;

            // Assert
            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
            Assert.Contains("5MB", _controller.ModelState["teachingMaterialImage"]!.Errors[0].ErrorMessage);
        }

        [Theory]
        [InlineData(".jpg")]
        [InlineData(".jpeg")]
        [InlineData(".png")]
        [InlineData(".gif")]
        [InlineData(".bmp")]
        public void Create_POST_AllowedExtensions_DoNotTriggerValidationError(string extension)
        {
            // Arrange
            var course = new Course { CourseID = 5550 + extension.GetHashCode() % 1000, Title = "Test", Credits = 3, DepartmentID = 1 };
            var fileMock = new Mock<IFormFile>();
            fileMock.Setup(f => f.Length).Returns(100);
            fileMock.Setup(f => f.FileName).Returns($"image{extension}");
            fileMock.Setup(f => f.CopyTo(It.IsAny<System.IO.Stream>()));

            // Act
            var result = _controller.Create(course, fileMock.Object);

            // Assert — should not have teachingMaterialImage error for allowed extensions
            Assert.False(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        #endregion

        #region Edit GET

        [Fact]
