            Assert.Equal(4, context.Departments.Count());
            var names = context.Departments.Select(d => d.Name).OrderBy(n => n).ToList();
            Assert.Equal(new[] { "Economics", "Engineering", "English", "Mathematics" }, names);
            context.Dispose();
        }

        [Fact]
        public void Initialize_EmptyDb_SeedsCourses()
        {
            var context = TestDbContextHelper.CreateContext();
            DbInitializer.Initialize(context);

            Assert.Equal(7, context.Courses.Count());
            Assert.Contains(context.Courses, c => c.Title == "Chemistry");
            Assert.Contains(context.Courses, c => c.Title == "Literature");
            context.Dispose();
        }

        [Fact]
        public void Initialize_EmptyDb_SeedsOfficeAssignments()
        {
            var context = TestDbContextHelper.CreateContext();
            DbInitializer.Initialize(context);

            Assert.Equal(3, context.OfficeAssignments.Count());
            Assert.Contains(context.OfficeAssignments, o => o.Location == "Smith 17");
            context.Dispose();
        }

        [Fact]
        public void Initialize_EmptyDb_SeedsEnrollments()
        {
            var context = TestDbContextHelper.CreateContext();
            DbInitializer.Initialize(context);

            Assert.Equal(11, context.Enrollments.Count());
            context.Dispose();
        }

        [Fact]
        public void Initialize_EmptyDb_SeedsCourseAssignments()
        {
            var context = TestDbContextHelper.CreateContext();
            DbInitializer.Initialize(context);

            Assert.Equal(8, context.CourseAssignments.Count());
            context.Dispose();
        }

        [Fact]
        public void Initialize_AlreadySeeded_DoesNotDuplicate()
        {
            // Arrange — seed once
            var context = TestDbContextHelper.CreateContext();
            DbInitializer.Initialize(context);
            var studentCount = context.Students.Count();

            // Act — seed again
            DbInitializer.Initialize(context);

            // Assert — count should be the same (early return because Students.Any() is true)
            Assert.Equal(studentCount, context.Students.Count());
            context.Dispose();
        }

        [Fact]
        public void Initialize_EnrollmentGrades_AreCorrect()
        {
            var context = TestDbContextHelper.CreateContext();
