            // Alexander got A in Chemistry (CourseID 1050)
            var enrollment = context.Enrollments.FirstOrDefault(e =>
                e.Student.LastName == "Alexander" && e.Course.Title == "Chemistry");
            // Can't use navigation props easily with in-memory, so check by IDs
            var alexander = context.Students.First(s => s.LastName == "Alexander");
            var chemistry = context.Courses.First(c => c.Title == "Chemistry");
            var alexChemistry = context.Enrollments.FirstOrDefault(e =>
                e.StudentID == alexander.ID && e.CourseID == chemistry.CourseID);
            Assert.NotNull(alexChemistry);
            Assert.Equal(Grade.A, alexChemistry.Grade);
            context.Dispose();
        }

        [Fact]
        public void Initialize_DepartmentBudgets_ArePositive()
        {
            var context = TestDbContextHelper.CreateContext();
            DbInitializer.Initialize(context);

            Assert.All(context.Departments, d => Assert.True(d.Budget > 0, $"Department {d.Name} has non-positive budget"));
            context.Dispose();
        }
    }
}

