                .Include(s => s.Enrollments)
                .First(s => s.ID == 10);

            Assert.Equal(2, student.Enrollments.Count);
        }

        [Fact]
        public void Enrollment_GradeIsNullable()
        {
            // Add an enrollment without a grade
            _context.Enrollments.Add(new Enrollment
            {
                StudentID = 12,
                CourseID = 1050,
                Grade = null
            });
            _context.SaveChanges();

            var enrollment = _context.Enrollments.First(e => e.StudentID == 12 && e.CourseID == 1050);
            Assert.Null(enrollment.Grade);
        }

        [Fact]
        public void CourseAssignment_CompositeKey_Works()
        {
            var ca = _context.CourseAssignments.Find(1050, 3);
            Assert.NotNull(ca);
            Assert.Equal(1050, ca.CourseID);
            Assert.Equal(3, ca.InstructorID);
        }

