        public void Department_InstructorID_Nullable()
        {
            var dept = new Department
            {
                Name = "No Admin Dept",
                Budget = 50000,
                StartDate = DateTime.Now,
                InstructorID = null
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var saved = _context.Departments.First(d => d.Name == "No Admin Dept");
            Assert.Null(saved.InstructorID);
        }

