        public void UpdateStudent_PersistsChange()
        {
            var student = _context.Students.Find(10)!;
            student.LastName = "Modified";
            _context.SaveChanges();

            // Re-read from context
            var updated = _context.Students.Find(10)!;
            Assert.Equal("Modified", updated.LastName);
        }

