namespace ContosoUniversity.Tests
{
    public class DbInitializerTests
    {
        [Fact]
        public void Initialize_EmptyDb_SeedsStudents()
        {
            // Arrange
            var context = TestDbContextHelper.CreateContext();

            // Act
            DbInitializer.Initialize(context);

            // Assert
            Assert.Equal(8, context.Students.Count());
            Assert.Contains(context.Students, s => s.LastName == "Alexander");
            Assert.Contains(context.Students, s => s.LastName == "Olivetto");
            context.Dispose();
        }

        [Fact]
        public void Initialize_EmptyDb_SeedsInstructors()
        {
            var context = TestDbContextHelper.CreateContext();
            DbInitializer.Initialize(context);

            Assert.Equal(5, context.Instructors.Count());
            Assert.Contains(context.Instructors, i => i.LastName == "Abercrombie");
            Assert.Contains(context.Instructors, i => i.LastName == "Zheng");
            context.Dispose();
        }

        [Fact]
        public void Initialize_EmptyDb_SeedsDepartments()
        {
            var context = TestDbContextHelper.CreateContext();
            DbInitializer.Initialize(context);

            Assert.Equal(4, context.Departments.Count());
            var names = context.Departments.Select(d => d.Name).OrderBy(n => n).ToList();
            Assert.Equal(new[] { "Economics", "Engineering", "English", "Mathematics" }, names);
            context.Dispose();
        }

        [Fact]
        public void Initialize_EmptyDb_SeedsCourses()
        {
            var context = TestDbContextHelper.CreateContext();
            DbInitializer.Initialize(context);

            Assert.Equal(7, context.Courses.Count());
            Assert.Contains(context.Courses, c => c.Title == "Chemistry");
            Assert.Contains(context.Courses, c => c.Title == "Literature");
            context.Dispose();
        }

        [Fact]
        public void Initialize_EmptyDb_SeedsOfficeAssignments()
        {
            var context = TestDbContextHelper.CreateContext();
            DbInitializer.Initialize(context);

            Assert.Equal(3, context.OfficeAssignments.Count());
            Assert.Contains(context.OfficeAssignments, o => o.Location == "Smith 17");
            context.Dispose();
        }

        [Fact]
        public void Initialize_EmptyDb_SeedsEnrollments()
        {
            var context = TestDbContextHelper.CreateContext();
            DbInitializer.Initialize(context);

            Assert.Equal(11, context.Enrollments.Count());
            context.Dispose();
        }

        [Fact]
        public void Initialize_EmptyDb_SeedsCourseAssignments()
        {
            var context = TestDbContextHelper.CreateContext();
            DbInitializer.Initialize(context);

            Assert.Equal(8, context.CourseAssignments.Count());
            context.Dispose();
        }

        [Fact]
        public void Initialize_AlreadySeeded_DoesNotDuplicate()
        {
            // Arrange — seed once
            var context = TestDbContextHelper.CreateContext();
            DbInitializer.Initialize(context);
            var studentCount = context.Students.Count();

            // Act — seed again
            DbInitializer.Initialize(context);

            // Assert — count should be the same (early return because Students.Any() is true)
            Assert.Equal(studentCount, context.Students.Count());
            context.Dispose();
        }

        [Fact]
        public void Initialize_EnrollmentGrades_AreCorrect()
        {
            var context = TestDbContextHelper.CreateContext();
            DbInitializer.Initialize(context);

            // Alexander got A in Chemistry (CourseID 1050)
            var enrollment = context.Enrollments.FirstOrDefault(e =>
                e.Student.LastName == "Alexander" && e.Course.Title == "Chemistry");
            // Can't use navigation props easily with in-memory, so check by IDs
            var alexander = context.Students.First(s => s.LastName == "Alexander");
            var chemistry = context.Courses.First(c => c.Title == "Chemistry");
            var alexChemistry = context.Enrollments.FirstOrDefault(e =>
                e.StudentID == alexander.ID && e.CourseID == chemistry.CourseID);
            Assert.NotNull(alexChemistry);
            Assert.Equal(Grade.A, alexChemistry.Grade);
            context.Dispose();
        }

        [Fact]
        public void Initialize_DepartmentBudgets_ArePositive()
        {
            var context = TestDbContextHelper.CreateContext();
            DbInitializer.Initialize(context);

            Assert.All(context.Departments, d => Assert.True(d.Budget > 0, $"Department {d.Name} has non-positive budget"));
            context.Dispose();
        }
    }
}

