using System;
using System.Collections.Generic;
using System.Linq;
using System.Net;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    /// <summary>
    /// Additional tests targeting mutation-gap findings: boundary conditions,
    /// off-by-one, case sensitivity, exact boundary dates, etc.
    /// </summary>
    public class BoundaryAndEdgeCaseTests
    {
        #region PaginatedList Boundary Tests

        [Fact]
        public void HasPreviousPage_PageIndexZero_ReturnsFalse()
        {
            // Mutation guard: > 1 vs >= 1 — PageIndex = 0 should have no previous page
            var list = new PaginatedList<int>(new List<int>(), 50, 0, 10);
            Assert.False(list.HasPreviousPage);
        }

        [Fact]
        public void HasNextPage_PageIndexEqualsTotalPages_ReturnsFalse()
        {
            // Mutation guard: < vs <= — when PageIndex == TotalPages, no next page
            // count=20, pageSize=10 => TotalPages=2; PageIndex=2
            var list = new PaginatedList<int>(new List<int>(), 20, 2, 10);
            Assert.Equal(2, list.TotalPages); // confirm TotalPages
            Assert.False(list.HasNextPage);   // must be false
        }

        [Fact]
        public void HasNextPage_PageIndexOneLessThanTotal_ReturnsTrue()
        {
            // PageIndex=1, TotalPages=2 => has next
            var list = new PaginatedList<int>(new List<int>(), 20, 1, 10);
            Assert.True(list.HasNextPage);
        }

        [Fact]
        public void Create_PageIndex1_SkipsZeroElements()
        {
            // Guard against off-by-one: Skip((1-1)*10) = Skip(0)
            var source = Enumerable.Range(100, 5).AsQueryable();
            var result = PaginatedList<int>.Create(source, 1, 10);
            Assert.Equal(100, result[0]); // first element is 100, not skipped
        }

        [Fact]
        public void Create_PageIndex2_SkipsExactlyPageSizeElements()
        {
            // Guard: Skip((2-1)*3) = Skip(3) — should start at item 4
            var source = Enumerable.Range(1, 10).AsQueryable();
            var result = PaginatedList<int>.Create(source, 2, 3);
            Assert.Equal(4, result[0]);
            Assert.Equal(5, result[1]);
            Assert.Equal(6, result[2]);
            Assert.Equal(3, result.Count);
        }

        #endregion

        #region StudentsController Boundary Date Tests

        [Fact]
        public void Create_POST_ExactBoundaryDate_1753_IsValid()
        {
            // Boundary: exactly 1753-01-01 should be VALID (not < 1753-01-01)
            using var context = TestDbContextHelper.CreateSeededContext();
            using var controller = new StudentsController(context);

            var student = new Student
            {
                FirstMidName = "Boundary",
                LastName = "Lower",
                EnrollmentDate = new DateTime(1753, 1, 1)
            };

            var result = controller.Create(student) as RedirectToActionResult;
            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
        }

        [Fact]
        public void Create_POST_OneDayBefore1753_IsInvalid()
        {
            // Date 1752-12-31 should be rejected
            using var context = TestDbContextHelper.CreateSeededContext();
            using var controller = new StudentsController(context);

            var student = new Student
            {
                FirstMidName = "Too",
                LastName = "Old",
                EnrollmentDate = new DateTime(1752, 12, 31)
            };

            var result = controller.Create(student) as ViewResult;
            Assert.NotNull(result);
            Assert.True(controller.ModelState.ContainsKey("EnrollmentDate"));
        }

        [Fact]
        public void Create_POST_ExactBoundaryDate_9999_IsValid()
        {
            // Boundary: exactly 9999-12-31 should be valid (not > 9999-12-31)
            using var context = TestDbContextHelper.CreateSeededContext();
            using var controller = new StudentsController(context);

            var student = new Student
            {
                FirstMidName = "Far",
                LastName = "Future",
                EnrollmentDate = new DateTime(9999, 12, 31)
            };

            var result = controller.Create(student) as RedirectToActionResult;
            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
        }

        [Fact]
        public void Edit_POST_ExactBoundaryDate_1753_IsValid()
        {
            using var context = TestDbContextHelper.CreateSeededContext();
            using var controller = new StudentsController(context);

            var existing = context.Students.Find(10);
            context.Entry(existing!).State = EntityState.Detached;

            var student = new Student
            {
                ID = 10,
                FirstMidName = "Carson",
                LastName = "Alexander",
                EnrollmentDate = new DateTime(1753, 1, 1)
            };

            var result = controller.Edit(student) as RedirectToActionResult;
            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
        }

        [Fact]
        public void Index_PageSize10_ReturnsAtMost10Students()
        {
            // Guard against pageSize mutations (10 -> 11 or 5)
            using var context = TestDbContextHelper.CreateContext();
            // Add 15 students
            for (int i = 0; i < 15; i++)
            {
                context.Students.Add(new Student
                {
                    FirstMidName = $"Student{i}",
                    LastName = $"Last{i:D2}",
                    EnrollmentDate = DateTime.Today
                });
            }
            context.SaveChanges();

            using var controller = new StudentsController(context);
            var result = controller.Index(null, null, null, null) as ViewResult;
            var model = Assert.IsType<PaginatedList<Student>>(result!.Model);

            Assert.Equal(10, model.Count); // pageSize = 10
            Assert.Equal(2, model.TotalPages); // ceil(15/10) = 2
        }

        #endregion

        #region CoursesController File Upload Boundary Tests

        [Fact]
        public void Create_POST_ExactlyFiveMB_Allowed()
        {
            // Guard: > 5MB, so exactly 5MB should be allowed
            using var context = TestDbContextHelper.CreateSeededContext();
            var envMock = new Mock<IWebHostEnvironment>();
            envMock.Setup(e => e.WebRootPath).Returns((string?)null);
            envMock.Setup(e => e.ContentRootPath).Returns(System.IO.Path.GetTempPath());
            var loggerMock = new Mock<ILogger<CoursesController>>();
            using var controller = new CoursesController(context, envMock.Object, loggerMock.Object);

            var course = new Course { CourseID = 5555, Title = "Boundary", Credits = 3, DepartmentID = 1 };
            var fileMock = new Mock<IFormFile>();
            fileMock.Setup(f => f.Length).Returns(5 * 1024 * 1024); // exactly 5MB
            fileMock.Setup(f => f.FileName).Returns("exact5mb.jpg");
            fileMock.Setup(f => f.CopyTo(It.IsAny<System.IO.Stream>()));

            var result = controller.Create(course, fileMock.Object);

            // Should NOT have file size error
            Assert.False(controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        [Fact]
        public void Create_POST_OneByteTooLarge_Rejected()
        {
            // Guard: exactly 5MB + 1 byte should be rejected
            using var context = TestDbContextHelper.CreateSeededContext();
            var envMock = new Mock<IWebHostEnvironment>();
            envMock.Setup(e => e.WebRootPath).Returns((string?)null);
            envMock.Setup(e => e.ContentRootPath).Returns(System.IO.Path.GetTempPath());
            var loggerMock = new Mock<ILogger<CoursesController>>();
            using var controller = new CoursesController(context, envMock.Object, loggerMock.Object);

            var course = new Course { CourseID = 5556, Title = "TooBig", Credits = 3, DepartmentID = 1 };
            var fileMock = new Mock<IFormFile>();
            fileMock.Setup(f => f.Length).Returns(5 * 1024 * 1024 + 1);
            fileMock.Setup(f => f.FileName).Returns("toobig.jpg");

            var result = controller.Create(course, fileMock.Object) as ViewResult;

            Assert.NotNull(result);
            Assert.True(controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        [Fact]
        public void Create_POST_UpperCaseExtension_Allowed()
        {
            // Guard: .ToLower() on the extension — uppercase .JPG should be allowed
            using var context = TestDbContextHelper.CreateSeededContext();
            var envMock = new Mock<IWebHostEnvironment>();
            envMock.Setup(e => e.WebRootPath).Returns((string?)null);
            envMock.Setup(e => e.ContentRootPath).Returns(System.IO.Path.GetTempPath());
            var loggerMock = new Mock<ILogger<CoursesController>>();
            using var controller = new CoursesController(context, envMock.Object, loggerMock.Object);

            var course = new Course { CourseID = 5557, Title = "UpperCase", Credits = 3, DepartmentID = 1 };
            var fileMock = new Mock<IFormFile>();
            fileMock.Setup(f => f.Length).Returns(100);
            fileMock.Setup(f => f.FileName).Returns("image.JPG");
            fileMock.Setup(f => f.CopyTo(It.IsAny<System.IO.Stream>()));

            var result = controller.Create(course, fileMock.Object);

            Assert.False(controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        [Fact]
        public void Create_POST_MixedCaseExtension_Allowed()
        {
            using var context = TestDbContextHelper.CreateSeededContext();
            var envMock = new Mock<IWebHostEnvironment>();
            envMock.Setup(e => e.WebRootPath).Returns((string?)null);
            envMock.Setup(e => e.ContentRootPath).Returns(System.IO.Path.GetTempPath());
            var loggerMock = new Mock<ILogger<CoursesController>>();
            using var controller = new CoursesController(context, envMock.Object, loggerMock.Object);

            var course = new Course { CourseID = 5558, Title = "MixedCase", Credits = 3, DepartmentID = 1 };
            var fileMock = new Mock<IFormFile>();
            fileMock.Setup(f => f.Length).Returns(100);
            fileMock.Setup(f => f.FileName).Returns("photo.Png");
            fileMock.Setup(f => f.CopyTo(It.IsAny<System.IO.Stream>()));

            var result = controller.Create(course, fileMock.Object);

            Assert.False(controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        #endregion

        #region NotificationService Boundary Tests

        [Fact]
        public void SendNotification_EmptyUserName_UsesEmptyStringNotSystem()
