            var list = new PaginatedList<int>(new List<int>(), 50, 0, 10);
            Assert.False(list.HasPreviousPage);
        }

        [Fact]
        public void HasNextPage_PageIndexEqualsTotalPages_ReturnsFalse()
        {
            // Mutation guard: < vs <= — when PageIndex == TotalPages, no next page
            // count=20, pageSize=10 => TotalPages=2; PageIndex=2
            var list = new PaginatedList<int>(new List<int>(), 20, 2, 10);
            Assert.Equal(2, list.TotalPages); // confirm TotalPages
            Assert.False(list.HasNextPage);   // must be false
        }

        [Fact]
        public void HasNextPage_PageIndexOneLessThanTotal_ReturnsTrue()
        {
            // PageIndex=1, TotalPages=2 => has next
            var list = new PaginatedList<int>(new List<int>(), 20, 1, 10);
            Assert.True(list.HasNextPage);
        }

        [Fact]
        public void Create_PageIndex1_SkipsZeroElements()
        {
            // Guard against off-by-one: Skip((1-1)*10) = Skip(0)
            var source = Enumerable.Range(100, 5).AsQueryable();
            var result = PaginatedList<int>.Create(source, 1, 10);
            Assert.Equal(100, result[0]); // first element is 100, not skipped
        }

