+        {
+            // Guard: changing grouping key would break this test
+            using var context = TestDbContextHelper.CreateContext();
+            var date1 = new DateTime(2020, 9, 1);
+            var date2 = new DateTime(2021, 9, 1);
+            context.Students.Add(new Student { FirstMidName = "A", LastName = "One", EnrollmentDate = date1 });
+            context.Students.Add(new Student { FirstMidName = "B", LastName = "Two", EnrollmentDate = date1 });
+            context.Students.Add(new Student { FirstMidName = "C", LastName = "Three", EnrollmentDate = date2 });
+            context.SaveChanges();
+
+            using var controller = new HomeController(context);
+            var result = controller.About() as ViewResult;
+            var data = Assert.IsAssignableFrom<System.Collections.Generic.List<Models.SchoolViewModels.EnrollmentDateGroup>>(result!.Model);
+
+            Assert.Equal(2, data.Count); // 2 distinct dates
+            var group1 = data.First(g => g.EnrollmentDate == date1);
+            Assert.Equal(2, group1.StudentCount);
+            var group2 = data.First(g => g.EnrollmentDate == date2);
+            Assert.Equal(1, group2.StudentCount);
+        }
+
+        #endregion
+    }
